function Show-Message([string]$text) {
  $control.Notice.Text = $text
}
function Invoke-Ui([scriptblock]$action) {
  try { & $action } catch { Show-Message $_.Exception.Message }
}
function Read-Json([string]$path) {
  if (Test-Path -LiteralPath $path) { return ConvertFrom-Json ([IO.File]::ReadAllText($path)) }
}
function Commit-File([string]$temporary,[string]$path) {
  $backup = $temporary + '.bak'
  for ($attempt=0; $attempt -lt 3; $attempt++) {
    try {
      if ([IO.File]::Exists($path)) { [IO.File]::Replace($temporary,$path,$backup) }
      else { [IO.File]::Move($temporary,$path) }
      break
    } catch [IO.IOException] {
      if ($attempt -eq 2 -or -not [IO.File]::Exists($temporary)) { throw }
      Start-Sleep -Milliseconds 120
    }
  }
  if ([IO.File]::Exists($backup)) { Remove-Item -LiteralPath $backup -Force -ErrorAction SilentlyContinue }
}
function Write-Text([string]$path,[string]$value) {
  $temporary = "$path.$([guid]::NewGuid().ToString('N')).tmp"
  try {
    [IO.File]::WriteAllText($temporary,$value,$UTF8)
    Commit-File $temporary $path
  } finally {
    if ([IO.File]::Exists($temporary)) { [IO.File]::Delete($temporary) }
  }
}
function Write-Json([string]$path,$value) {
  Write-Text $path ($value | ConvertTo-Json -Depth 8 -Compress)
}
function Profile-Path([string]$login,[string]$broker,[string]$symbol) {
  $hash = [Security.Cryptography.SHA256]::Create()
  try {
    $bytes = $UTF8.GetBytes("$login`n$broker`n$symbol")
    $digest = [BitConverter]::ToString($hash.ComputeHash($bytes)).Replace('-','').ToLowerInvariant()
    return Join-Path $Profiles $digest
  } finally { $hash.Dispose() }
}
function Get-Number($field,[double]$minimum,[double]$maximum,[string]$label) {
  [double]$value = 0
  $raw = $field.Text.Trim().Replace(',','.')
  if (-not [double]::TryParse($raw,[Globalization.NumberStyles]::AllowDecimalPoint,
                              [Globalization.CultureInfo]::InvariantCulture,[ref]$value) -or
      $value -lt $minimum -or $value -gt $maximum) {
    throw "$label ต้องอยู่ระหว่าง $minimum ถึง $maximum"
  }
  return $value
}
function Load-Risk([string]$profilePath) {
  $risk = $null
  if ($profilePath) { $risk = Read-Json (Join-Path $profilePath 'risk.json') }
  if (-not $risk) { $risk = $DefaultRisk }
  $control.PerTrade.Text = [string]$risk.perTrade
  $control.Total.Text = [string]$risk.total
  $control.Daily.Text = [string]$risk.daily
  $control.Positions.Text = [string]$risk.positions
  $control.Hedging.IsChecked = [bool]$risk.hedging
}

function Install-App {
  $manifest = Join-Path $App '.installed'
  $payloadId = 'eb0117a79f16986d88564bd37308e94d40ec5d01a29a258a488028fd02ac06d7'
  if ([IO.File]::Exists($manifest) -and [IO.File]::ReadAllText($manifest) -eq $payloadId -and
      [IO.File]::Exists((Join-Path $App 'mobile-signin.js')) -and [IO.File]::Exists((Join-Path $App 'login.html')) -and [IO.File]::Exists((Join-Path $App 'server.mjs')) -and
      [IO.File]::Exists((Join-Path $App 'Run-SMC.ps1'))) { return }
  New-Item -ItemType Directory -Path $Root -Force | Out-Null
  $stage = Join-Path $Root ("stage-" + [guid]::NewGuid().ToString('N'))
  try {
    $bytes = [Convert]::FromBase64String($Archive)
    $stream = [IO.MemoryStream]::new($bytes)
    try {
      $zip = [IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Read)
      try { [IO.Compression.ZipFileExtensions]::ExtractToDirectory($zip,$stage) }
      finally { $zip.Dispose() }
    } finally { $stream.Dispose() }
    [IO.File]::WriteAllText((Join-Path $stage '.installed'),$payloadId,$UTF8)
    if (Test-Path -LiteralPath $App) {
      Move-Item -LiteralPath $App -Destination ($App + ".previous-" + [guid]::NewGuid().ToString('N'))
    }
    Move-Item -LiteralPath $stage -Destination $App
  } finally {
    if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Recurse -Force }
  }
}
function Install-Shortcut {
  if ($control.Shortcut.IsChecked) {
    $desktop = [Environment]::GetFolderPath('DesktopDirectory')
    if ([IO.Directory]::Exists($desktop)) {
      $link = (New-Object -ComObject WScript.Shell).CreateShortcut((Join-Path $desktop 'OI Gold SMC AI Trader.lnk'))
      $link.TargetPath = $PowerShell
      $link.Arguments = '-NoLogo -NoProfile -STA -WindowStyle Hidden -ExecutionPolicy Bypass -File "' + $PSCommandPath + '"'
      $link.IconLocation = (Join-Path $Root 'OI-Gold-SMC-Setup-x64.exe') + ',0' 
      $link.WorkingDirectory = $Root
      $link.Description = 'OI Gold SMC AI Trader'
      $link.Save()
    }
  }
}

$script:LegacyPhoneFiles = @{ owner='phone-owner-password.txt'; viewer='phone-password.txt' }

function Get-PhonePassword([string]$profilePath,[string]$role) {
  $saved = Read-Json (Join-Path $profilePath 'phone-auth.json')
  if ($saved) {
    $encrypted = if ($role -eq 'owner') { $saved.owner } else { $saved.viewer }
    if ($encrypted) {
      $secret = ConvertTo-SecureString $encrypted
      try { return [Net.NetworkCredential]::new('',$secret).Password }
      finally { $secret.Dispose() }
    }
  }
  $legacy = Join-Path $profilePath ($LegacyPhoneFiles[$role])
  if ([IO.File]::Exists($legacy)) { return [IO.File]::ReadAllText($legacy).Trim() }
}

function Resolve-PhonePasswords([string]$profilePath) {
  $passwords = @{ owner=$control.OwnerPassword.Password; viewer=$control.ViewerPassword.Password }
  foreach ($role in @('owner','viewer')) {
    $value = $passwords[$role]
    if (-not $value) { $value = Get-PhonePassword $profilePath $role }
    if (-not $value) { $value = [guid]::NewGuid().ToString('N') }
    $value = $value.Normalize([Text.NormalizationForm]::FormC)
    if ($value.Length -lt 15 -or $value.Length -gt 128 -or $value -match '[\x00-\x1f\x7f]') {
      throw "รหัส $role ต้องมี 15–128 ตัวอักษร"
    }
    $passwords[$role] = $value
  }
  if ([string]::Equals($passwords.owner,$passwords.viewer,[StringComparison]::Ordinal)) {
    throw 'รหัส owner และ viewer ต้องต่างกัน'
  }
  return $passwords
}

function Save-PhonePasswords([string]$profilePath,$passwords) {
  $path = Join-Path $profilePath 'phone-auth.json'
  if (-not (Test-Path -LiteralPath $path) -or $control.OwnerPassword.Password -or $control.ViewerPassword.Password) {
    $protected = @{}
    foreach ($role in @('owner','viewer')) {
      $secret = ConvertTo-SecureString ($passwords[$role]) -AsPlainText -Force
      try { $protected[$role] = ConvertFrom-SecureString $secret }
      finally { $secret.Dispose() }
    }
    Write-Json $path $protected
  }
  foreach ($name in $LegacyPhoneFiles.Values) {
    Remove-Item -LiteralPath (Join-Path $profilePath $name) -Force -ErrorAction SilentlyContinue
  }
}
$script:formPath = Join-Path $Root 'launcher-form-v1.json'
$script:textNames = @('Login','Broker','Symbol','Model','PerTrade','Total','Daily','Positions')
$script:checkNames = @('UsePhone','Shortcut','Hedging')
$script:secretNames = @('GoKey','OwnerPassword','ViewerPassword')
$script:formDirty = $false
$script:formReady = $false
$script:formEdits = @{}
function Store-Form {
  if (!$formReady -or !$formDirty) { return }
  $record = [ordered]@{}
  foreach ($name in $textNames) { $record[$name] = $control[$name].Text }
  foreach ($name in $checkNames) { $record[$name] = [bool]$control[$name].IsChecked }
  foreach ($name in $secretNames) {
    $secure = $control[$name].SecurePassword
    try { $record[$name] = if ($secure.Length) { ConvertFrom-SecureString $secure } else { '' } }
    finally { $secure.Dispose() }
  }
  $record['edited'] = @($formEdits.Keys)
  [void][IO.Directory]::CreateDirectory($Root)
  Write-Json $formPath $record
  $script:formDirty = $false
}
function Restore-Form($snapshot,$hasSettings) {
  if (!$snapshot) { return }
  foreach ($n in @($snapshot.edited)) { if ($n) { $formEdits[$n]=$true } }
  foreach ($n in @($textNames + $checkNames + $secretNames)) {
    if ($hasSettings -and !$formEdits.ContainsKey($n)) { continue }
    $prop = $snapshot.PSObject.Properties[$n]
    if ($null -eq $prop) { continue }
    if (!$hasSettings -and $CurrentProfile -and $n -in @('Login','Broker','Symbol') -and !$formEdits.ContainsKey($n) -and !$prop.Value) { continue }
    if ($textNames -contains $n) { $control[$n].Text=[string]$prop.Value }
    elseif ($checkNames -contains $n) { $control[$n].IsChecked=[bool]$prop.Value }
    elseif ($prop.Value) {
      $sec = ConvertTo-SecureString $prop.Value
      try { $control[$n].Password=[Net.NetworkCredential]::new('',$sec).Password } finally { $sec.Dispose() }
    } else { $control[$n].Clear() }
  }
}
function Register-Form {
  $changed = { param($sender,$eventArgs)
    if ($script:formReady -and $sender.IsKeyboardFocusWithin) {
      $script:formEdits[$sender.Name]=$true
      $script:formDirty=$true
    }
  }
  foreach ($n in $textNames) { $control[$n].Add_TextChanged($changed) }
  foreach ($n in $checkNames) { $control[$n].Add_Click({param($sender,$eventArgs) $script:formEdits[$sender.Name]=$true; $script:formDirty=$true}) }
  foreach ($n in $secretNames) { $control[$n].Add_PasswordChanged($changed) }
  $script:formReady=$true
}
function Recover-Identity {
  $common=Join-Path $env:APPDATA 'MetaQuotes\Terminal\Common\Files'
  $hits=@(foreach ($file in @(Get-ChildItem -LiteralPath $common -Filter 'OI-SMC-Bridge-*.txt' -File -ErrorAction SilentlyContinue)) {
    if ($file.BaseName -notmatch '^OI-SMC-Bridge-([0-9]+)$') { continue }
    $id=$Matches[1]
    $rows=[IO.File]::ReadAllLines($file.FullName)
    if ($rows.Count -lt 4 -or $rows[0] -cne 'OI_SMC_BRIDGE_V1') { continue }
    $profileDir=Profile-Path $id $rows[1] $rows[2]
    $tokenFile=Join-Path $profileDir 'bridge-token.txt'
    if ([IO.File]::Exists($tokenFile) -and [IO.File]::ReadAllText($tokenFile).Trim() -ceq $rows[3].Trim()) {
      [pscustomobject]@{login=$id;broker=$rows[1];symbol=$rows[2];directory=$profileDir}
    }
  })
  if ($hits.Count -eq 1) {
    $control.Login.Text=$hits[0].login
    $control.Broker.Text=$hits[0].broker
    $control.Symbol.Text=$hits[0].symbol
    $script:CurrentProfile=$hits[0].directory
    Load-Risk $CurrentProfile
    $control.CopyToken.IsEnabled=$true
  }
}

function Fill-PhoneFields {
  if (!$CurrentProfile) { return }
  foreach ($role in @('owner','viewer')) {
    $legacy=if ($role -eq 'owner') {'phone-owner-password.txt'} else {'phone-password.txt'}
    if ([IO.File]::Exists((Join-Path $CurrentProfile 'phone-auth.json')) -or [IO.File]::Exists((Join-Path $CurrentProfile $legacy))) {
      $control[($role+'Password')].Password=[string](Get-PhonePassword $CurrentProfile $role)
    }
  }
}

function Save-Configuration {
  Store-Form
  $login = $control.Login.Text.Trim()
  $broker = $control.Broker.Text.Trim()
  $symbol = $control.Symbol.Text.Trim()
  $model = $control.Model.Text.Trim()
  if ($login -notmatch '^[0-9]{1,20}$' -or $login -match '^0+$') { throw 'กรอกเลขบัญชี MT5 ให้ถูกต้อง' }
  $login = $login -replace '^0+',''
  if (-not $broker -or $broker -match '[\x00-\x1f<>"/\\|?*:]') { throw 'กรอกชื่อเซิร์ฟเวอร์ตามที่แสดงใน MT5' }
  if (-not $symbol -or $symbol -match '[\x00-\x20]') { throw 'กรอกชื่อ Symbol ให้ตรงกับกราฟ MT5 เช่น XAUUSDc' }
  if ($model -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$') { throw 'กรอก ID โมเดล OpenCode Go เช่น gpt-6-luna' }
  $profilePath = Profile-Path $login $broker $symbol
  $risk = [ordered]@{
    enabled=$false; hedging=[bool]$control.Hedging.IsChecked;
    perTrade=(Get-Number $control.PerTrade 0.01 ([double]::MaxValue) 'ความเสี่ยงต่อไม้');
    total=(Get-Number $control.Total 0.01 ([double]::MaxValue) 'ความเสี่ยงรวม');
    daily=(Get-Number $control.Daily 0 ([double]::MaxValue) 'Daily DD');
    positions=(Get-Number $control.Positions 1 50 'จำนวนไม้สูงสุด')
  }
  if ($risk.total -lt $risk.perTrade) { throw 'ความเสี่ยงรวมต้องไม่น้อยกว่าความเสี่ยงต่อไม้' }
  if ([math]::Floor($risk.positions) -ne $risk.positions) { throw 'จำนวนไม้สูงสุดต้องเป็นจำนวนเต็ม' }
  $risk.positions = [int]$risk.positions
  $encrypted = $script:StoredKey
  if ($control.GoKey.SecurePassword.Length -gt 0) {
    if ($control.GoKey.SecurePassword.Length -lt 10) { throw 'ตรวจสอบ API key ของ OpenCode Go' }
    $encrypted = ConvertFrom-SecureString $control.GoKey.SecurePassword
  }
  if (-not $encrypted) { throw 'กรอก API key ของ OpenCode Go' }
  $phonePasswords = Resolve-PhonePasswords $profilePath
  Install-App
  New-Item -ItemType Directory -Path $profilePath -Force | Out-Null
  $tokenPath = Join-Path $profilePath 'bridge-token.txt'
  if (-not [IO.File]::Exists($tokenPath)) {
    [IO.File]::WriteAllText($tokenPath, [guid]::NewGuid().ToString('N'), $UTF8)
  }
  Save-PhonePasswords $profilePath $phonePasswords
  $riskPath = Join-Path $profilePath 'risk.json'
  $old = Read-Json $riskPath
  if (-not $old -or $old.perTrade -ne $risk.perTrade -or $old.total -ne $risk.total -or $old.daily -ne $risk.daily -or
      $old.positions -ne $risk.positions -or $old.hedging -ne $risk.hedging) {
    if ($old) { $risk.enabled = [bool]$old.enabled }
    Write-Json $riskPath $risk
  }
  $prefs = [ordered]@{ version=$Version; login=$login; broker=$broker; symbol=$symbol; model=$model; goKey=$encrypted; phone=[bool]$control.UsePhone.IsChecked; shortcut=[bool]$control.Shortcut.IsChecked }
  Write-Json $Prefs $prefs
  $script:StoredKey = $encrypted
  $control.KeyStatus.Text = 'บันทึกคีย์แบบเข้ารหัสแล้ว กรอกอีกครั้งเมื่อต้องการเปลี่ยน'
  $script:CurrentProfile = $profilePath
  $control.CopyOwner.IsEnabled=$true; $control.CopyViewer.IsEnabled=$true
  $control.CopyToken.IsEnabled = $true
  $script:SetupNote = ''
  $script:AutoLink = $false
  try {
    $common = Join-Path $env:APPDATA 'MetaQuotes\Terminal\Common\Files'
    New-Item -ItemType Directory -Path $common -Force | Out-Null
    $linkFile = Join-Path $common ("OI-SMC-Bridge-" + $login + ".txt")
    $token = [IO.File]::ReadAllText($tokenPath).Trim()
    Write-Text $linkFile ((@('OI_SMC_BRIDGE_V1',$broker,$symbol,$token) -join [Environment]::NewLine) + [Environment]::NewLine)
    $script:AutoLink = $true
  } catch { $script:SetupNote = ' ตั้งค่าเชื่อมอัตโนมัติไม่สำเร็จ ให้ใช้ปุ่มคัดลอก Bridge Token' }
  try { Install-Shortcut }
  catch { $script:SetupNote += ' เปิด EXE จากไฟล์ที่แตกไว้ เนื่องจากอัปเดตทางลัดไม่สำเร็จ' }
  Fill-PhoneFields
  $script:formEdits.Clear()
  $script:formDirty=$true
  Store-Form
  return $prefs
}

function Find-Tool([string]$name) {
  $application = Get-Command "$name.exe" -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($application) { return $application.Source }
  $candidates = @((Join-Path $env:LOCALAPPDATA "Microsoft\WinGet\Links\$name.exe"))
  if ($name -eq 'node') { $candidates += Join-Path $env:ProgramFiles 'nodejs\node.exe' }
  if ($name -eq 'gh') { $candidates += Join-Path $env:ProgramFiles 'GitHub CLI\gh.exe' }
  foreach ($scope in @('User','Machine')) {
    $registered = [Environment]::GetEnvironmentVariable('Path',$scope)
    foreach ($directory in ($registered -split ';')) {
      if ($directory) {
        $expanded = [Environment]::ExpandEnvironmentVariables($directory.Trim('"'))
        if ([IO.Path]::IsPathRooted($expanded)) { $candidates += Join-Path $expanded "$name.exe" }
      }
    }
  }
  foreach ($path in $candidates) { if ([IO.File]::Exists($path)) { return $path } }
  return $null
}
function New-NodeProbe([string]$node) {
  $probe = New-Object Diagnostics.ProcessStartInfo
  $probe.FileName = $node
  $probe.Arguments = '-p process.versions.node'
  $probe.UseShellExecute = $false
  $probe.CreateNoWindow = $true
  $probe.RedirectStandardOutput = $true
  $process = [Diagnostics.Process]::Start($probe)
  try {
    $runtime = $process.StandardOutput.ReadToEnd().Trim()
    $process.WaitForExit()
    return $process.ExitCode -eq 0 -and $runtime -match '^\d+\.' -and [int]($runtime.Split('.')[0]) -ge 20
  } finally { $process.Dispose() }
}
function Set-Running([bool]$running) {
  $control.Fields.IsEnabled = -not $running
  $control.StartBot.IsEnabled = -not $running
  $control.SaveConfig.IsEnabled = -not $running
  $control.Dependencies.IsEnabled = -not $running
  $control.StopBot.IsEnabled = $running
  if (-not $running) { $control.Dashboard.IsEnabled = $false }
}
function Start-Backend {
  $prefs = Save-Configuration
  $node = Find-Tool 'node'
  if (-not $node -or -not (New-NodeProbe $node)) { throw 'ต้องใช้ Node.js 20 ขึ้นไป กด ติดตั้งเครื่องมือ เพื่อเปิดตัวติดตั้ง Node.js' }
  $cloud = $null
  if ($prefs.phone) {
    $cloud = Find-Tool 'cloudflared'
    if (-not $cloud) { $script:SetupNote += ' หากต้องการใช้มือถือ ให้กดติดตั้ง Cloudflare Tunnel หลังหยุดระบบ' }
  }
  if (Get-NetTCPConnection -State Listen -LocalPort @(4183,4184) -ErrorAction SilentlyContinue) {
    throw 'พอร์ต SMC ถูกใช้อยู่ ปิด SMC รุ่นที่เปิดค้างไว้ก่อน'
  }
  $runRoot = Join-Path $CurrentProfile 'run'
  $script:RunDir = Join-Path $runRoot ([guid]::NewGuid().ToString('N'))
  New-Item -ItemType Directory -Path $RunDir -Force | Out-Null
  Get-ChildItem -LiteralPath $runRoot -Directory -ErrorAction SilentlyContinue | Where-Object {
    $_.Name -match '^[0-9a-f]{32}$' -and $_.LastWriteTimeUtc -lt [DateTime]::UtcNow.AddDays(-7)
  } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
  $key = ConvertTo-SecureString $prefs.goKey
  $start = New-Object Diagnostics.ProcessStartInfo
  $start.FileName = $PowerShell
  $start.Arguments = '-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File "' + (Join-Path $App 'Run-SMC.ps1') + '"'
  $start.WorkingDirectory = $App
  $start.UseShellExecute = $false
  $start.CreateNoWindow = $true
  $variables = @{
    OI_SMC_NODE=$node; OI_SMC_TUNNEL=[string]$cloud; OI_SMC_GH=[string](Find-Tool 'gh');
    OI_SMC_STATE_DIR=$CurrentProfile; OI_SMC_RUN_DIR=$RunDir; OI_SMC_PARENT=[string]$PID;
    OI_SMC_PARENT_TIME=[string]((Get-Process -Id $PID).StartTime.Ticks);
    OPENCODE_GO_API_KEY=[Net.NetworkCredential]::new('',$key).Password;
    OI_SMC_MODEL=$prefs.model; OI_MT5_LOGIN=$prefs.login; OI_MT5_SERVER=$prefs.broker;
    OI_MT5_SYMBOL=$prefs.symbol; OI_SMC_PORT='4183'; OI_SMC_VIEW_PORT='4184';
    OI_SMC_BRIDGE_TOKEN=[IO.File]::ReadAllText((Join-Path $CurrentProfile 'bridge-token.txt')).Trim();
    OI_SMC_FILE_QUEUE=(Join-Path "$env:APPDATA\MetaQuotes\Terminal\Common\Files" ("OI-SMC-Queue-" + $prefs.login));
    OI_SMC_JOURNAL_FILE=(Join-Path "$env:APPDATA\MetaQuotes\Terminal\Common\Files" ("OISMCJournal_" + $prefs.broker + "_" + $prefs.login + ".tsv"))
  }
  foreach ($pair in $variables.GetEnumerator()) { $start.EnvironmentVariables[$pair.Key] = [string]$pair.Value }
  $start.EnvironmentVariables.Remove('OI_VIEW_PASSWORD')
  $start.EnvironmentVariables.Remove('OI_PHONE_OWNER_PASSWORD')
  if ($cloud) {
    $start.EnvironmentVariables['OI_PHONE_OWNER_PASSWORD'] = Get-PhonePassword $CurrentProfile 'owner'
    $start.EnvironmentVariables['OI_VIEW_PASSWORD'] = Get-PhonePassword $CurrentProfile 'viewer'
  }
  try { $script:Worker = [Diagnostics.Process]::Start($start) }
  finally {
    $start.EnvironmentVariables.Remove('OPENCODE_GO_API_KEY')
    $start.EnvironmentVariables.Remove('OI_PHONE_OWNER_PASSWORD')
    $start.EnvironmentVariables.Remove('OI_VIEW_PASSWORD')
  }
  $variables.OPENCODE_GO_API_KEY = ''
  $script:LastLog = ''
  $script:PhoneInfo = $null
  $script:WasReady = $false
  $control.Logs.Visibility = 'Collapsed'
  $control.DirectLink.Clear(); $control.CopyDirect.IsEnabled=$false
    $control.PhoneStatus.Text = ''
  $control.State.Text = 'กำลังเปิดระบบ'
  Show-Message 'กำลังเชื่อมต่อแดชบอร์ด SMC'
  Set-Running $true
}
function Copy-Value([string]$value,[string]$label) {
  if (-not $value) { Show-Message "ยังไม่มี $label"; return }
  try {
    Add-Type -AssemblyName System.Windows.Forms
    [System.Windows.Forms.Clipboard]::SetDataObject($value,$true,10,120)
    Show-Message "คัดลอก $label แล้ว"
    return
  } catch {
    Show-Message "คลิปบอร์ดยังไม่พร้อม คัดลอก $label ไม่สำเร็จ"
  }
  $choice = [System.Windows.MessageBox]::Show($window,"ต้องการแสดง $label บนหน้าจอเพื่อคัดลอกเองหรือพิมพ์ตามหรือไม่",$label,'YesNo','Question','No')
  if ($choice -ne [System.Windows.MessageBoxResult]::Yes) { return }
  $dialog = [System.Windows.Window]::new()
  $dialog.Title = $label
  $dialog.Owner = $window
  $dialog.WindowStartupLocation = 'CenterOwner'
  $dialog.Width = 500
  $dialog.SizeToContent = 'Height'
  $panel = [System.Windows.Controls.StackPanel]::new()
  $panel.Margin = 16
  $hint = [System.Windows.Controls.TextBlock]::new()
  $hint.Text = 'กด Ctrl+C เพื่อลองคัดลอกอีกครั้ง หรือพิมพ์ค่าตามที่แสดง'
  $hint.TextWrapping = 'Wrap'
  $box = [System.Windows.Controls.TextBox]::new()
  $box.Text = $value
  $box.IsReadOnly = $true
  $box.TextWrapping = 'Wrap'
  $box.FontFamily = 'Consolas'
  $close = [System.Windows.Controls.Button]::new()
  $close.Content = 'ปิด'
  $close.IsCancel = $true
  foreach ($item in @($hint,$box,$close)) { [void]$panel.Children.Add($item) }
  $dialog.Content = $panel
  $dialog.Add_ContentRendered({ [void]$box.Focus(); $box.SelectAll() })
  try { [void]$dialog.ShowDialog() } finally { $box.Clear() }
}
function Request-Stop {
  if ($script:Worker -and -not $script:Worker.HasExited) {
    [IO.File]::WriteAllText((Join-Path $RunDir 'stop'),'stop',$UTF8)
    $control.StopBot.IsEnabled = $false
    $control.State.Text = 'กำลังหยุดระบบ'
  }
}
function Install-Tools {
  if ($script:ToolInstaller -and -not $script:ToolInstaller.HasExited) { throw 'ตัวติดตั้งเครื่องมือกำลังทำงาน' }
  $winget = Find-Tool 'winget'
  if (-not $winget) { throw 'ต้องใช้ App Installer (winget) ของ Windows ในการติดตั้งเครื่องมือจากปุ่มนี้' }
  $node = Find-Tool 'node'
  if (-not $node -or -not (New-NodeProbe $node)) { $package='OpenJS.NodeJS.LTS' }
  elseif ($control.UsePhone.IsChecked -and -not (Find-Tool 'cloudflared')) { $package='Cloudflare.cloudflared' }
  else { Show-Message 'เครื่องมือที่ต้องใช้สำหรับโหมดนี้พร้อมแล้ว'; return }
  $script:ToolInstaller = Start-Process -FilePath $winget -ArgumentList @('install','--exact','--id',$package,'--accept-package-agreements','--accept-source-agreements') -PassThru
  Show-Message "กำลังติดตั้ง $package แล้วจึงกด บันทึกและเปิดระบบ"
}
function Refresh-Worker {
  if (-not $script:Worker) { return }
  $status = Read-Json (Join-Path $RunDir 'status.json')
  if ($status -and $status.ready -and -not $script:WasReady) {
    $script:WasReady = $true
    $control.Dashboard.IsEnabled = $true
    $control.State.Text = '● ระบบกำลังทำงาน'
    $hint = if ($AutoLink) { ' เปิด EA 1.05 บนกราฟ M5 เพื่อเชื่อมอัตโนมัติ' } else { '' }
    Show-Message ('เปิดแดชบอร์ดได้แล้ว' + $hint + $SetupNote)
  }
  $info = Read-Json (Join-Path $RunDir 'phone.json')
  if ($info -and ![IO.File]::Exists((Join-Path $RunDir 'mobile-reconnect'))) {
    $script:PhoneInfo = $info
    $control.ReconnectPhone.IsEnabled = $true
    $control.CopyPhone.IsEnabled = [bool]$info.url
    $control.CopyOwner.IsEnabled = [bool]$CurrentProfile
    $control.CopyViewer.IsEnabled = [bool]$CurrentProfile
    $control.DirectLink.Text=[string]$info.direct
    $control.CopyDirect.IsEnabled=[bool]$info.direct
    $control.PhoneStatus.Text = $info.message
  }
  $logPath = Join-Path $RunDir 'node-error.log'
  if (Test-Path -LiteralPath $logPath) {
    try {
      $lines = @(Get-Content -LiteralPath $logPath -Tail 6 -ErrorAction Stop)
      $now = $lines -join [Environment]::NewLine
      if ($now -and $now -ne $script:LastLog) {
         $script:LastLog = $now; $control.Logs.Text = $now; $control.Logs.Visibility = 'Visible'
      }
    } catch { }
  }
  if ($script:Worker.HasExited) {
    $exitCode = $script:Worker.ExitCode
    $script:Worker.Dispose()
    $script:Worker = $null
    Set-Running $false
    $control.State.Text = 'ระบบหยุดแล้ว'
    $control.CopyPhone.IsEnabled = $false
    $control.ReconnectPhone.IsEnabled = $false
    $control.CopyOwner.IsEnabled = [bool]$CurrentProfile
    $control.CopyViewer.IsEnabled = [bool]$CurrentProfile
    $control.DirectLink.Clear(); $control.CopyDirect.IsEnabled=$false
    $control.PhoneStatus.Text = ''
    if ($CurrentProfile) { Load-Risk $CurrentProfile }
    if ($status -and $status.error) { Show-Message $status.error }
    elseif ($exitCode -ne 0) { Show-Message "เปิด SMC ไม่สำเร็จ (รหัส $exitCode)" }
    else { Show-Message 'หยุดแดชบอร์ด SMC แล้ว' }
  }
}

function Fit-StartupWindow($window) {
  $work = [System.Windows.SystemParameters]::WorkArea
  if ($work.Width -le 0 -or $work.Height -le 0) { return }
  $margin = 8.0
  $sizedWidth = [Math]::Max(1.0, $work.Width - 2 * $margin)
  $sizedHeight = [Math]::Max(1.0, $work.Height - 2 * $margin)
  $window.MinWidth = [Math]::Min($window.MinWidth, $sizedWidth)
  $window.MinHeight = [Math]::Min($window.MinHeight, $sizedHeight)
  $window.Width = [Math]::Min($window.Width, $sizedWidth)
  $window.Height = [Math]::Min($window.Height, $sizedHeight)
  $window.Left = $work.Left + ($work.Width - $window.Width) / 2
  $window.Top = $work.Top + ($work.Height - $window.Height) / 2
}

$mutex = [Threading.Mutex]::new($false,'Local\OIGoldSMCSetup101')
$locked = $false
try {
  try { $locked = $mutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $locked = $true }
  if (-not $locked) { [System.Windows.MessageBox]::Show('หน้าต่าง SMC เปิดอยู่แล้ว','OI Gold SMC') | Out-Null; exit 0 }
  $reader = [Xml.XmlNodeReader]::new($layout)
  $window = [System.Windows.Markup.XamlReader]::Load($reader)
  $control = @{}
  foreach ($item in $layout.SelectNodes('//*[@Name]')) { $name = $item.GetAttribute('Name'); $control[$name] = $window.FindName($name) }
  try { $saved = Read-Json $Prefs } catch { $saved=$null }
  if ($saved -and (!$saved.login -or !$saved.broker -or !$saved.symbol)) { $saved=$null }
  if ($saved) {
    $control.Login.Text = $saved.login
    $control.Broker.Text = $saved.broker
    $control.Symbol.Text = $saved.symbol
    $control.Model.Text = $saved.model
    $control.UsePhone.IsChecked = [bool]$saved.phone
    $control.Shortcut.IsChecked = [bool]$saved.shortcut
    $script:StoredKey = $saved.goKey
    $script:CurrentProfile = Profile-Path $saved.login $saved.broker $saved.symbol
    $control.CopyToken.IsEnabled = [IO.File]::Exists((Join-Path $CurrentProfile 'bridge-token.txt'))
    $control.KeyStatus.Text = 'บันทึกคีย์แบบเข้ารหัสแล้ว กรอกอีกครั้งเมื่อต้องการเปลี่ยน'
    Load-Risk $CurrentProfile
  } else { $control.KeyStatus.Text = 'ใช้ API key ของแพ็กเกจ OpenCode Go' }
  try { $snapshot=Read-Json $formPath } catch { $snapshot=$null }
  if (!$saved) { Recover-Identity }
  if ($saved -and $saved.goKey) {
    $secret=ConvertTo-SecureString $saved.goKey
    try { $control.GoKey.Password=[Net.NetworkCredential]::new('',$secret).Password } finally { $secret.Dispose() }
  }
  Fill-PhoneFields
  Restore-Form $snapshot ([bool]$saved)
  Register-Form
  $control.SaveConfig.Add_Click({ Invoke-Ui { $null = Save-Configuration; Show-Message ('บันทึกบัญชีและติดตั้งแดชบอร์ดแล้ว' + $SetupNote) } })
  $control.StartBot.Add_Click({ Invoke-Ui { Start-Backend } })
  $control.StopBot.Add_Click({ Invoke-Ui { Request-Stop } })
  $control.Dashboard.Add_Click({ Invoke-Ui { Start-Process ($LocalUrl + '/') } })
  $control.Dependencies.Add_Click({ Invoke-Ui { Install-Tools } })
  $control.CopyBridge.Add_Click({ Invoke-Ui { Copy-Value $LocalUrl 'URL สำหรับ MT5' } })
  $control.CopyToken.Add_Click({ Invoke-Ui { Copy-Value ([IO.File]::ReadAllText((Join-Path $CurrentProfile 'bridge-token.txt')).Trim()) 'Bridge Token' } })
  $control.CopyDirect.Add_Click({ Invoke-Ui { Copy-Value $control.DirectLink.Text 'ลิงก์ตรง' } })
  $control.CopyOwner.IsEnabled=[bool]$CurrentProfile
  $control.CopyViewer.IsEnabled=[bool]$CurrentProfile
  $control.CopyPhone.Add_Click({ Invoke-Ui { Copy-Value $PhoneInfo.url 'ลิงก์มือถือ' } })
  $control.ReconnectPhone.Add_Click({ Invoke-Ui {
    if ($script:Worker -and -not $script:Worker.HasExited -and $RunDir) {
      [IO.File]::WriteAllText((Join-Path $RunDir 'mobile-reconnect'),'restart',$UTF8)
      $control.PhoneStatus.Text = 'ส่งคำขอเชื่อมมือถือใหม่แล้ว'
      $control.CopyPhone.IsEnabled = $false
      $control.CopyDirect.IsEnabled = $false
      $control.DirectLink.Clear()
      $script:PhoneInfo = $null
    }
  } })
  $control.CopyOwner.Add_Click({ Invoke-Ui { Copy-Value (Get-PhonePassword $CurrentProfile 'owner') 'รหัส owner' } })
  $control.CopyViewer.Add_Click({ Invoke-Ui { Copy-Value (Get-PhonePassword $CurrentProfile 'viewer') 'รหัส viewer' } })
  $timer = [System.Windows.Threading.DispatcherTimer]::new()
  $timer.Interval = [TimeSpan]::FromMilliseconds(800)
  $timer.Add_Tick({ Invoke-Ui { Store-Form; Refresh-Worker } })
  $timer.Start()
  $window.Add_Closing({ param($sender,$e)
    try { Store-Form } catch { $e.Cancel=$true; Show-Message $_.Exception.Message; return }
    try { Request-Stop } catch { }
  })
  Fit-StartupWindow $window
  [void]$window.ShowDialog()
  $timer.Stop()
} catch {
  [System.Windows.MessageBox]::Show($_.Exception.Message,'OI Gold SMC Setup') | Out-Null
} finally {
  if ($locked) { $mutex.ReleaseMutex() }
  $mutex.Dispose()
}
